    let col = pos.col;
    if (row.flags(col) & WIDE_CHAR_SPACER) col--;
    if (sep(col)) return { abs: pos.abs, col };
    while (col + dir >= 0 && col + dir < this.term.cols && !sep(col + dir)) col += dir;
    if (dir > 0 && (row.flags(col) & WIDE_CHAR)) col++;
